let state={tasks:initialTasks,docs:initialDocs,habits:initialHabits,theme:'light'};try{const saved=JSON.parse(localStorage.getItem('nando-prototype-v1'));if(saved)state={...state,...saved}}catch(e){}
let view='dashboard',currentArea='Salute',currentSpace='',taskId=2,docId=1,habitId=1,collapsed=false,habitFilter='',localQuery='',searchIndex=0,searchMatches=[],dialogAction=null;
const app=document.getElementById('app'),today='2026-10-28';
function persist(){try{localStorage.setItem('nando-prototype-v1',JSON.stringify(state))}catch(e){}}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,2800)}
function dateLabel(d){return d?new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit'}):'Senza scadenza'}
function openCount(a){return state.tasks.filter(t=>!t.done&&t.area===a).length}
function nav(v,arg){view=v;if(v==='area'){currentArea=arg;currentSpace=''}if(v==='space'){currentSpace=arg;currentArea=areas.find(a=>[...a.projects,...a.resources,...a.sub].includes(arg))?.name||currentArea}if(v==='habit-detail'){habitId=Number(arg);habitAnalyticsYear=Number(today.slice(0,4));}if(v==='task')taskId=Number(arg);if(v==='document')docId=Number(arg);localQuery='';render();window.scrollTo(0,0)}
function navButton(v,label,ico,arg,extra=''){return `<button class="nav-item ${(view===v||(v==='habits'&&view==='habit-detail'))&&(v!=='area'||arg===currentArea)?'active':''}" data-nav="${v}" ${arg?`data-arg="${esc(arg)}"`:''} title="${esc(label)}">${icon(ico)}<span class="hide-rail od-field">${label}${extra}</span></button>`}
function crumb(){if(view==='habit-detail'){const h=state.habits.find(h=>h.id===habitId);return `<button data-nav="habits">Habit</button> <span>/</span> ${esc(h?.name||'Dettaglio')}`;}if(view==='task'){const t=findTask(t=>t.id===taskId);return `${esc(t.area||'Inbox')} <span>/</span> ${esc(t.space)} <span>/</span> <span class="current">Task</span>`}if(view==='document'){const d=state.docs.find(d=>d.id===docId);return `${esc(d.area)} <span>/</span> ${esc(d.space)} <span>/</span> <span class="current">Documento</span>`}if(view==='area'||view==='space')return `${esc(currentArea)}${currentSpace?' <span>/</span> '+esc(currentSpace):''}`;return {dashboard:'Dashboard',knowledge:'Knowledge',habits:'Habit',areas:'Aree',inbox:'Inbox',calendar:'Calendario'}[view]||'Nando'}
function render(){document.documentElement.dataset.theme=state.theme;app.innerHTML=`<aside class="sidebar ${collapsed?'collapsed':''}" data-screen="shell"><div class="brand"><span class="brand-mark">n</span><span class="hide-rail">nando</span><button class="icon-btn" data-action="collapse" aria-label="Comprimi o espandi navigazione">${icon('panel')}</button></div><button class="btn capture" data-action="capture" title="Cattura rapida">${icon('plus')}<span class="hide-rail">Cattura rapida</span><span class="hide-rail key" style="margin-left:auto">C</span></button><nav class="nav-group">${navButton('dashboard','Dashboard','grid')}${navButton('calendar','Calendario','calendar')}${navButton('inbox','Inbox','inbox','',`<small>${state.tasks.filter(t=>t.space==='Inbox'&&!t.done).length} da organizzare</small>`)}</nav><nav class="nav-group"><div class="nav-label">Le tue aree</div>${areas.map(a=>navButton('area',a.name,a.icon,a.name,`<small>${a.projects.length} ${a.projects.length===1?'progetto':'progetti'}</small>`)).join('')}</nav><nav class="nav-group">${navButton('habits','Habit','habit')}${navButton('knowledge','Knowledge','book')}</nav><div class="side-bottom"><button class="nav-item" data-action="search" title="Ricerca">${icon('search')}<span class="hide-rail">Ricerca</span><span class="hide-rail key" style="margin-left:auto">⌘ K</span></button><div class="user-row"><span class="user-monogram">TU</span><span class="od-field"><strong>Spazio personale</strong><small class="muted">Solo tu, tutto qui</small></span></div></div></aside><div class="main-shell ${collapsed?'rail':''}"><header class="topbar"><div class="breadcrumbs">${icon(view==='dashboard'?'grid':'folder')}<button data-nav="dashboard">Nando</button><span>/</span>${crumb()}</div><button class="top-search" data-action="search">${icon('search')} Cerca <span class="key">⌘ K</span></button><button class="icon-btn" data-action="theme" aria-label="${state.theme==='light'?'Attiva tema scuro':'Attiva tema chiaro'}">${icon(state.theme==='light'?'sun':'moon')}</button><button class="btn" data-action="capture">${icon('plus')} Nuovo</button><button class="icon-btn mobile-new" data-action="capture" aria-label="Nuovo elemento" style="display:none">${icon('plus')}</button></header><main class="content ${['task','document'].includes(view)?'reading':''}" id="main">${page()}</main></div><nav class="bottom-nav" aria-label="Navigazione principale">${[['dashboard','Dashboard','grid'],['calendar','Calendario','calendar'],['areas','Aree','folder'],['habits','Habit','habit'],['search','Cerca','search']].map(([v,l,i])=>`<button ${v==='search'?'data-action="search"':`data-nav="${v}"`} class="${(view===v||(v==='habits'&&view==='habit-detail'))?'active':''}">${icon(i)}<span>${l}</span></button>`).join('')}</nav>`;if(view==='habits')centerHabitToday()}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function tasks(rows){if(!rows.length)return `<div class="empty"><h3>Niente per oggi</h3><p>Uno spazio libero per ciò che conta.</p><button class="btn" data-action="capture">Cattura un pensiero</button></div>`;return `<div class="task-list">${rows.map(t=>`<div class="task-row"><input type="checkbox" data-check-task="${t.id}" ${t.done?'checked':''} aria-label="Completa ${esc(t.title)}"><button class="task-name ${t.done?'done':''}" data-nav="task" data-arg="${t.id}">${esc(t.title)}</button><span class="task-space" title="${esc(t.space)}">${esc(t.space)}</span>${t.date&&t.date<today&&!t.done?'<span class="pill">In ritardo</span>':''}<span class="task-date">${t.date===today?'Tutto il giorno':dateLabel(t.date)}</span></div>`).join('')}</div>`}
function habitWeekDays(){return Array.from({length:7},(_,i)=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()-i);return {key:isoDay(d),day:d.getDate(),weekday:d.toLocaleDateString('it-IT',{weekday:'short'}),full:d.toLocaleDateString('it-IT',{day:'numeric',month:'long'})}})}
function habitMini(h){const complete=h.n>=h.target;return `<tr class="habit-week-row ${h.paused?'paused':''}"><th scope="row"><button class="habit-week-name" data-nav="habit-detail" data-arg="${h.id}">${esc(h.name)}</button><span class="habit-week-target">${h.paused?'In pausa':`${h.n}/${h.target} · ${h.period==='mese'?'mese':h.period==='settimana'?'sett.':'giorno'}`}</span></th>${habitWeekDays().map(d=>{const n=h.checkins?.[d.key]||0;const paused=h.paused&&d.key>='2026-10-15';const label=paused?'In pausa':n?`${n} check-in`:'Storico non disponibile';return `<td class="${d.key===today?'week-today':''}"><span class="habit-history-cell ${n?'recorded':''} ${paused?'paused':''}" title="${esc(h.name)} · ${d.full}: ${label}" aria-label="${esc(h.name)} · ${d.full}: ${label}">${paused?icon('pause'):n?(n>1?String(n):icon('check')):'—'}</span></td>`}).join('')}<td><button class="habit-week-check ${complete?'is-complete':''}" data-check-habit="${h.id}" ${h.paused||complete?'disabled':''} title="${h.paused?'In pausa':complete?'Obiettivo raggiunto':'Check-in di oggi'}" aria-label="${h.paused?'In pausa':complete?'Obiettivo raggiunto per':'Check-in di oggi per'} ${esc(h.name)}">${icon(h.paused?'pause':complete?'check':'plus')}</button></td></tr>`}
function habitWeekSummary(){return `<table class="habit-week-table"><caption class="sr-only">Registrazioni giornaliere delle abitudini negli ultimi sette giorni</caption><colgroup><col class="habit-name-col">${habitWeekDays().map(()=>'<col class="habit-day-col">').join('')}<col class="habit-action-col"></colgroup><thead><tr><th scope="col"><span class="sr-only">Abitudine e obiettivo del periodo</span></th>${habitWeekDays().map(d=>`<th scope="col" class="${d.key===today?'week-today':''}"><span class="od-cell"><span>${esc(d.weekday)}</span><strong>${d.day}</strong></span></th>`).join('')}<th scope="col"><span class="sr-only">Check-in</span></th></tr></thead><tbody>${state.habits.map(habitMini).join('')}</tbody></table><p class="habit-week-help">Ultimi 7 giorni · + check-in oggi<br><span>— storico non disponibile · Ⅱ in pausa</span></p>`}
paths.pause='M8 5v14 M16 5v14';
function docRow(d){return `<button class="doc-row" data-nav="document" data-arg="${d.id}">${icon('file')}<span class="od-field od-fill"><strong>${esc(d.title)}</strong><small>${esc(d.space)}</small></span><small>${esc(d.modified)}</small></button>`}
let quickTaskDraft={open:false,title:'',date:'2026-10-28',done:false};
function quickTaskRow(){if(!quickTaskDraft.open)return `<button class="add-row" data-quick-task-open>${icon('plus')} Aggiungi un task</button>`;return `<div class="quick-task-create"><div class="quick-task-fields"><input type="checkbox" id="quick-task-done" ${quickTaskDraft.done?'checked':''} aria-label="Task già completato"><label class="quick-task-title"><span class="sr-only">Nome del task</span><input id="quick-task-name" value="${esc(quickTaskDraft.title)}" placeholder="Nome del task" autocomplete="off" aria-describedby="quick-task-error"></label><label class="quick-task-date"><span class="sr-only">Scadenza del task</span><input type="date" id="quick-task-date" value="${esc(quickTaskDraft.date)}" aria-label="Scadenza"></label><button type="button" class="btn" data-quick-task-save>Salva</button></div><p class="error" id="quick-task-error" role="alert" hidden></p></div>`}
function saveQuickTask(){const name=document.getElementById('quick-task-name'),date=document.getElementById('quick-task-date'),done=document.getElementById('quick-task-done');if(!name)return;const title=name.value.trim();if(!title){const error=document.getElementById('quick-task-error');error.textContent='Inserisci il nome del task.';error.hidden=false;name.setAttribute('aria-invalid','true');name.focus();return}const task={id:Date.now(),title,date:date.value,done:done.checked,space:'Inbox',area:'',props:{},localProps:[]};state.tasks.push(task);persist();quickTaskDraft={open:false,title:'',date:today,done:false};render();document.querySelector('[data-quick-task-open]')?.focus();toast(task.done?'Task salvato come completato':!task.date?'Task salvato in Inbox':task.date>today?'Task salvato. Lo trovi tra i prossimi impegni.':'Task aggiunto a Oggi')}
document.addEventListener('click',e=>{if(e.target.closest('[data-quick-task-open]')){quickTaskDraft.open=true;render();document.getElementById('quick-task-name')?.focus()}if(e.target.closest('[data-quick-task-save]'))saveQuickTask()});
document.addEventListener('input',e=>{if(e.target.id==='quick-task-name'){quickTaskDraft.title=e.target.value;e.target.removeAttribute('aria-invalid');document.getElementById('quick-task-error').hidden=true}if(e.target.id==='quick-task-date')quickTaskDraft.date=e.target.value;if(e.target.id==='quick-task-done')quickTaskDraft.done=e.target.checked});
document.addEventListener('keydown',e=>{if(!e.target.closest('.quick-task-create'))return;if(e.key==='Enter'&&e.target.tagName==='INPUT'&&e.target.type!=='date'){e.preventDefault();saveQuickTask()}if(e.key==='Escape'){e.preventDefault();quickTaskDraft={open:false,title:'',date:today,done:false};render();document.querySelector('[data-quick-task-open]')?.focus()}});
function dashboard(){const todays=state.tasks.filter(t=>!t.done&&t.date&&t.date<=today);const next=state.tasks.filter(t=>!t.done&&t.date>today&&t.date<='2026-11-04').sort((a,b)=>a.date.localeCompare(b.date));return `<div data-screen="dashboard"><div class="eyebrow">${icon('calendar')} Mercoledì 28 ottobre 2026</div>${heading('Un po’ di ordine, ogni giorno.','Tutto quello che conta, nel tuo spazio personale.','<button class="btn primary" data-action="capture">'+icon('plus')+' Cattura rapida</button>')}<div class="dash-grid"><div><section class="today-area"><div class="section-head"><h2>Oggi</h2><span class="number">${todays.length}</span><span class="pill blue" style="margin-left:auto">28 ottobre</span></div>${tasks(todays.slice(0,7))}${quickTaskRow()}</section><section class="section"><div class="section-head">${icon('calendar')}<h2>Prossimi 7 giorni</h2><span class="number">${next.length}</span></div>${next.length?tasks(next):'<p class="muted">Nessun impegno in programma.</p>'}</section><section class="habit-summary"><div class="section-head"><h2>Habit</h2><button class="text-btn" data-nav="habits">Apri Habit →</button></div>${habitWeekSummary()}</section></div><aside><section class="section"><div class="section-head">${icon('file')}<h2>Note recenti</h2><button class="text-btn" data-nav="knowledge">Tutte le note →</button></div><div class="notes-list">${[state.docs[1],state.docs[0],state.docs[2]].filter(Boolean).map(docRow).join('')}</div></section><section class="section"><div class="section-head"><h2>Progetti in corso</h2><span class="number">${areas.reduce((n,a)=>n+a.projects.length,0)}</span></div>${areas.flatMap(a=>a.projects.map(project=>`<button class="area-mini" data-nav="space" data-arg="${esc(project)}">${icon(projectIcon(project))}<span class="od-field od-fill"><strong>${esc(project)}</strong><small>${esc(a.name)}</small></span><span class="arrow">${icon('arrow')}</span></button>`)).join('')}</section><button class="inbox-panel" data-nav="inbox">${icon('inbox')}<span class="od-field"><strong>Inbox</strong><small>Un posto per iniziare, senza organizzare.</small></span><span class="number">${state.tasks.filter(t=>!t.done&&t.space==='Inbox').length}</span>${icon('arrow')}</button></aside></div></div>`}
