const projectIconChoices=[['folder','Cartella'],['briefcase','Lavoro'],['code','Sviluppo'],['target','Obiettivo'],['heart','Salute'],['users','Persone'],['book','Studio'],['calendar','Calendario'],['leaf','Natura'],['home','Casa'],['star','Stella'],['music','Musica'],['pen','Scrittura'],['coffee','Pausa'],['habit','Costanza'],['grid','Organizzazione'],['file','Documento'],['sun','Sole'],['moon','Luna'],['inbox','Raccolta']];
let iconPickerProject='';
function projectIcon(project){const choice=state.projectIcons?.[project];return projectIconChoices.some(([key])=>key===choice)?choice:'folder'}
function iconPickerDialog(){let d=document.getElementById('project-icon-dialog');if(!d){d=document.createElement('dialog');d.id='project-icon-dialog';d.setAttribute('aria-labelledby','project-icon-title');document.body.appendChild(d);d.addEventListener('close',()=>document.querySelector('[data-project-icon]')?.focus())}return d}
function renderProjectIconChoices(query=''){const selected=projectIcon(iconPickerProject),choices=projectIconChoices.filter(([,label])=>label.toLocaleLowerCase('it-IT').includes(query.trim().toLocaleLowerCase('it-IT')));document.getElementById('project-icon-grid').innerHTML=choices.length?choices.map(([key,label])=>`<button type="button" class="project-icon-option ${selected===key?'selected':''}" data-project-icon-choice="${key}" aria-label="${label}" aria-pressed="${selected===key}">${icon(key)}<span>${label}</span></button>`).join(''):'<p class="muted">Nessuna icona trovata.</p>'}
function openProjectIconPicker(project){if(!areas.some(a=>a.projects.includes(project)))return;iconPickerProject=project;const d=iconPickerDialog();d.innerHTML=`<div class="od-row"><div class="od-fill"><h2 id="project-icon-title">Icona del progetto</h2><p class="small muted">${esc(project)}</p></div><button type="button" class="icon-btn" data-project-icon-close aria-label="Chiudi">×</button></div><label class="project-icon-search" for="project-icon-search">Cerca un’icona<input id="project-icon-search" placeholder="Es. Studio, Sviluppo, Salute" autocomplete="off"></label><div class="project-icon-grid" id="project-icon-grid"></div><button type="button" class="text-btn" data-project-icon-choice="folder">Ripristina cartella</button>`;renderProjectIconChoices();d.showModal();document.getElementById('project-icon-search').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.projectIcon)openProjectIconPicker(b.dataset.projectIcon);if(b.hasAttribute('data-project-icon-close'))iconPickerDialog().close();if(b.dataset.projectIconChoice&&projectIconChoices.some(([key])=>key===b.dataset.projectIconChoice)){state.projectIcons=state.projectIcons||{};state.projectIcons[iconPickerProject]=b.dataset.projectIconChoice;persist();iconPickerDialog().close();render();document.querySelector('[data-project-icon]')?.focus();toast('Icona del progetto aggiornata')}});
