function areaPage(){const a=areas.find(a=>a.name===currentArea)||areas[0],specific=view==='space',sp=specific?currentSpace:a.name;const rows=state.tasks.filter(t=>!t.done&&(specific?t.space===sp:t.area===a.name));return `<div data-screen="area">${specific&&a.projects.includes(sp)?`<button class="page-icon project-icon-trigger" data-project-icon="${esc(sp)}" aria-label="Cambia icona di ${esc(sp)}" title="Cambia icona del progetto">${icon(projectIcon(sp))}</button>`:`<div class="page-icon">${icon(specific?'folder':a.icon)}</div>`}${heading(sp,specific?`${a.name} / ${a.resources.includes(sp)?'Risorsa':a.sub.includes(sp)?'Sotto-area':'Progetto'}`:'Area · Uno spazio per ciò che conta',`<button class="btn" data-action="edit-space">Modifica</button>`)}${state.descriptions?.[sp]?`<p class="muted" style="margin-bottom:24px">${esc(state.descriptions[sp])}</p>`:''}${specific&&sp==='Nando'?'<div class="notice">Fase <span class="pill blue">design</span> <span class="muted"> · Cliente —</span></div>':''}${!specific?`<div class="area-grid"><section class="section"><div class="section-head"><h2>Progetti</h2><span class="number">${a.projects.length}</span></div>${a.projects.map(p=>`<button class="space-row" data-nav="space" data-arg="${p}">${icon(projectIcon(p))}<span class="od-field"><strong>${p}</strong><small>${state.tasks.filter(t=>t.space===p&&!t.done).length} task aperti · Ultima attività 28/10</small></span>${p==='Nando'?'<span class="pill blue">design</span>':''}${icon('arrow')}</button>`).join('')}</section><section class="section"><div class="section-head"><h2>${a.sub.length?'Sotto-aree':'Risorse'}</h2></div>${(a.sub.length?a.sub:a.resources).map(p=>`<button class="space-row" data-nav="space" data-arg="${p}">${icon(a.sub.length?'moon':'book')}<span class="od-field"><strong>${p}</strong><small>${state.docs.filter(d=>d.space===p).length} documenti</small></span>${icon('arrow')}</button>`).join('')||'<p class="muted small">Nessuna risorsa in questa Area.</p>'}</section></div>`:''}<section class="section"><div class="section-head"><h2>Task aperti</h2><span class="number">${rows.length}</span><button class="text-btn" data-action="capture">+ Nuovo task</button></div>${rows.length?tasks(rows):'<div class="empty">Nessun task aperto in questo Space.</div>'}</section><section class="section"><div class="section-head"><h2>${!specific&&a.sub.length?'Risorse':'Documenti'}</h2></div>${!specific&&a.sub.length?a.resources.map(p=>`<button class="space-row" data-nav="space" data-arg="${p}">${icon('book')}<span class="od-field"><strong>${p}</strong><small>${state.docs.filter(d=>d.space===p).length} documenti · medico: —</small></span>${icon('arrow')}</button>`).join(''):state.docs.filter(d=>specific?d.space===sp:d.area===a.name).map(docRow).join('')||'<p class="muted">Nessun documento. Crea il primo da Knowledge.</p>'}</section>${specific?`<button class="btn" data-action="space-knowledge">${icon('book')} Apri Knowledge dello Space</button>`:''}</div>`}
function field(label,value,type='text',attrs=''){return `<div class="field"><label>${label}</label><input type="${type}" value="${esc(value)}" ${attrs} aria-label="${label}"></div>`}
