function cleanNoteHTML(html){const root=document.createElement('div');root.innerHTML=html;const allowed=new Set(['P','DIV','H1','H2','H3','UL','OL','LI','BLOCKQUOTE','PRE','CODE','STRONG','B','EM','I','U','S','STRIKE','BR']);function clean(node){for(const child of [...node.children]){if(['SCRIPT','STYLE','IFRAME','OBJECT'].includes(child.tagName)){child.remove();continue}clean(child);if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes);continue}for(const attr of [...child.attributes])child.removeAttribute(attr.name)}}clean(root);return root.innerHTML}
function taskNotesEditor(t){const html=t.noteHtml?cleanNoteHTML(t.noteHtml):t.note?esc(t.note).split('\n').map(line=>`<p>${line||'<br>'}</p>`).join(''):'';return `<section class="task-notes" aria-labelledby="notes-title"><div class="section-head"><h2 id="notes-title">Note</h2><span class="note-save-status" id="note-save-status" role="status">${t.note?'Modificabile direttamente':'Uno spazio libero per questo task'}</span></div><div class="note-editor-shell"><div class="note-toolbar" role="toolbar" aria-label="Formattazione delle note"><button type="button" data-note-command="formatBlock" data-note-value="p" title="Testo" aria-label="Blocco di testo">Testo</button><button type="button" data-note-command="formatBlock" data-note-value="h2" title="Titolo" aria-label="Blocco titolo">H2</button><span class="note-toolbar-divider" aria-hidden="true"></span><button type="button" data-note-command="bold" title="Grassetto" aria-label="Grassetto"><strong>B</strong></button><button type="button" data-note-command="italic" title="Corsivo" aria-label="Corsivo"><em>I</em></button><button type="button" data-note-command="strikeThrough" title="Barrato" aria-label="Barrato"><s>S</s></button><span class="note-toolbar-divider" aria-hidden="true"></span><button type="button" data-note-command="insertUnorderedList" title="Elenco puntato" aria-label="Elenco puntato">${icon('list')}</button><button type="button" data-note-command="insertOrderedList" title="Elenco numerato" aria-label="Elenco numerato">1.</button><button type="button" data-note-command="formatBlock" data-note-value="blockquote" title="Citazione" aria-label="Blocco citazione">❞</button><button type="button" data-note-command="formatBlock" data-note-value="pre" title="Codice" aria-label="Blocco di codice">&lt;/&gt;</button><span class="note-toolbar-divider" aria-hidden="true"></span><button type="button" data-note-command="undo" title="Annulla" aria-label="Annulla modifica">↶</button><button type="button" data-note-command="redo" title="Ripeti" aria-label="Ripeti modifica">↷</button></div><div id="task-note-editor" class="note-block-editor prose" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Note del task ${esc(t.title)}" aria-describedby="notes-hint" data-note-task="${t.id}" data-placeholder="Scrivi una nota, un’idea o una lista…" spellcheck="true">${html}</div></div><p id="notes-hint" class="note-editor-hint">Scrivi liberamente. Usa la barra per cambiare blocco o formattare il testo selezionato.</p></section>`}
