let noteSelection=null;
function saveTaskNote(editor){const t=findTask(t=>t.id===Number(editor.dataset.noteTask));if(!t)return;t.note=editor.innerText.replace(/\u00a0/g,' ').trim();t.noteHtml=t.note?cleanNoteHTML(editor.innerHTML):'';if(t.isDraft){const status=document.getElementById('note-save-status');if(status)status.textContent='Bozza non ancora creata';editor.dataset.empty=String(!t.note);return}let d=state.docs.find(d=>d.id===(t.noteDocId||(t.id===2?5:null)));if(!d&&t.note){d={id:Date.now(),title:`Nota di "${t.title}"`,space:t.space,area:t.area,kind:'note',excerpt:'',body:'',modified:'Oggi'};state.docs.push(d);t.noteDocId=d.id}if(d){d.body=t.note;d.excerpt=t.note.slice(0,60);d.modified='Oggi'}let saved=true;try{localStorage.setItem('nando-prototype-v1',JSON.stringify(state))}catch(e){saved=false}const status=document.getElementById('note-save-status');if(status)status.textContent=saved?'Salvato':'Conservato in questa sessione';editor.dataset.empty=String(!t.note)}
document.addEventListener('selectionchange',()=>{const editor=document.getElementById('task-note-editor'),selection=window.getSelection();if(editor&&selection?.rangeCount&&editor.contains(selection.anchorNode)&&editor.contains(selection.focusNode))noteSelection=selection.getRangeAt(0).cloneRange()});
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-note-command]'))e.preventDefault()});
document.addEventListener('click',e=>{const button=e.target.closest('[data-note-command]');if(!button)return;const editor=document.getElementById('task-note-editor');if(!editor)return;editor.focus();const selection=window.getSelection();if(noteSelection&&editor.contains(noteSelection.commonAncestorContainer)){selection.removeAllRanges();selection.addRange(noteSelection)}else{const range=document.createRange();range.selectNodeContents(editor);range.collapse(false);selection.removeAllRanges();selection.addRange(range)}document.execCommand(button.dataset.noteCommand,false,button.dataset.noteValue||null);saveTaskNote(editor)});
document.addEventListener('input',e=>{const editor=e.target.closest('#task-note-editor');if(editor)saveTaskNote(editor)});
document.addEventListener('paste',e=>{const editor=e.target.closest('#task-note-editor');if(!editor)return;e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));saveTaskNote(editor)});
document.addEventListener('drop',e=>{if(e.target.closest('#task-note-editor'))e.preventDefault()});
function taskLocalProperties(t){return `<div class="property-group task-local-properties" aria-label="Proprietà locali di questa entità">${(t.localProps||[]).map(p=>{const data=`data-local-prop="${esc(p.id)}" data-local-task="${t.id}" aria-label="${esc(p.name)}"`;const control=p.type==='checkbox'?`<label class="local-check"><input type="checkbox" ${data} ${p.value?'checked':''}><span>${p.value?'Sì':'No'}</span></label>`:`<input class="property-input" type="${p.type}" ${p.type==='number'?'step="any"':''} ${data} value="${esc(p.value)}" placeholder="Vuoto">`;return propertyRow(p.name,p.type==='date'?'calendar':p.type==='number'?'number':p.type==='checkbox'?'check':'text',control,'solo questa entità')}).join('')}</div><details class="add-task-property" id="add-task-property"><summary>${icon('plus')} Aggiungi proprietà locale</summary><div class="inline-property-form"><div class="inline-property-fields"><label for="local-prop-name">Nome della proprietà locale<input id="local-prop-name" maxlength="60" placeholder="Es. Priorità personale" autocomplete="off"></label><label for="local-prop-type">Tipo<select id="local-prop-type"><option value="text">Testo</option><option value="number">Numero</option><option value="date">Data</option><option value="checkbox">Casella di spunta</option><option value="url">Link</option></select></label></div><p class="small muted">Disponibile solo per questa entità. Non si eredita e non compare nelle viste.</p><p id="local-prop-error" class="error" role="alert" hidden></p><div class="od-row"><button type="button" class="btn" data-local-add="${t.id}">Aggiungi</button><button type="button" class="text-btn" data-local-cancel>Annulla</button></div></div></details>`}
function addLocalProperty(id){const task=findTask(t=>t.id===Number(id)),input=document.getElementById('local-prop-name'),error=document.getElementById('local-prop-error');if(!task||!input)return;if((task.localProps||[]).length>=20){error.textContent='Hai raggiunto il limite di 20 proprietà locali per questa entità.';error.hidden=false;input.setAttribute('aria-invalid','true');input.focus();return}const name=input.value.trim(),normalized=name.toLocaleLowerCase('it-IT'),existing=['Stato','Scadenza','Space','Ricorrenza',...Object.keys(task.props),...(task.localProps||[]).map(p=>p.name)];if(!name||existing.some(n=>n.toLocaleLowerCase('it-IT')===normalized)){error.textContent=!name?'Inserisci un nome per la proprietà.':'Questo nome è già utilizzato. Scegline uno diverso.';error.hidden=false;input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','local-prop-error');input.focus();return}const type=document.getElementById('local-prop-type').value;const p={id:'local-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name,type,value:type==='checkbox'?false:''};task.localProps=task.localProps||[];task.localProps.push(p);persist();render();document.querySelector(`[data-local-prop="${p.id}"]`)?.focus();toast('Proprietà locale aggiunta a questa entità')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.localAdd)addLocalProperty(b.dataset.localAdd);if(b.hasAttribute('data-local-cancel')){document.getElementById('add-task-property').open=false;document.querySelector('#add-task-property summary')?.focus()}});
document.addEventListener('keydown',e=>{if(e.target.id==='local-prop-name'&&e.key==='Enter'){e.preventDefault();addLocalProperty(taskId)}});
document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.localProp)return;const t=findTask(t=>t.id===Number(el.dataset.localTask)),p=t?.localProps?.find(p=>p.id===el.dataset.localProp);if(!p)return;p.value=p.type==='checkbox'?el.checked:el.value;if(p.type==='checkbox'){const label=el.parentElement.querySelector('span');if(label)label.textContent=p.value?'Sì':'No'}persist()});
let taskDraft=null,taskDraftReturn=null;
function findTask(predicate){return taskDraft&&predicate(taskDraft)?taskDraft:state.tasks.find(predicate)}
function openTaskDraft(){if(!taskDraft){taskDraftReturn={view,currentArea,currentSpace,taskId,docId,habitId};taskDraft={id:Date.now(),title:'',space:'Inbox',area:'',date:'',done:false,props:{},localProps:[],note:'',noteHtml:'',isDraft:true}}taskId=taskDraft.id;view='task';render();window.scrollTo(0,0);document.querySelector('.entity-title')?.focus()}
function taskDraftActions(t){return t.isDraft?`<div class="task-draft-header"><span class="pill">Nuovo task · Bozza</span><div class="od-row"><button type="button" class="btn" data-task-draft-cancel>Annulla</button><button type="button" class="btn primary" data-task-draft-create>Crea task</button></div></div>`:''}
function taskSpaceControl(t){return `<select id="task-space-select" class="property-select" data-move-task="${t.id}" aria-label="Space del task"><option value="Inbox" ${t.space==='Inbox'?'selected':''}>Inbox</option>${areas.map(a=>`<optgroup label="${a.name}">${[a.name,...a.sub,...a.projects,...a.resources].map(s=>`<option value="${esc(s)}" ${t.space===s?'selected':''}>${esc(s)}</option>`).join('')}</optgroup>`).join('')}</select>${!t.isDraft?`<button class="icon-btn" data-nav="${t.space==='Inbox'?'inbox':'space'}" data-arg="${esc(t.space)}" aria-label="Apri ${esc(t.space)}" title="Apri lo Space">${icon('arrow')}</button>`:''}`}
function moveTaskSpace(id,space){const task=findTask(t=>t.id===Number(id));if(!task||space===task.space)return;const area=areas.find(a=>[a.name,...a.sub,...a.projects,...a.resources].includes(space));if(space!=='Inbox'&&!area)return;const defs=area?.name==='Salute'?['frequenza',...(space==='Visita odontoiatrica'?['costo']:[])]:area?.name==='Lavoro'?['cliente',...(space==='Nando'?['stima']:[])]:area?.name==='Relazioni'?['occasione']:[];if(task.orphan&&!task.orphanProps&&!task.legacyOrphan)task.legacyOrphan=true;task.orphanProps=task.orphanProps||{};for(const [key,value] of Object.entries(task.props)){if(!defs.includes(key)&&value!==''&&value!==null&&value!==undefined)task.orphanProps[key]={value,space:task.space}}const props={};for(const key of defs){props[key]=Object.prototype.hasOwnProperty.call(task.props,key)?task.props[key]:task.orphanProps[key]?.value??'';delete task.orphanProps[key]}task.props=props;task.space=space;task.area=area?.name||'';task.orphanCount=Object.keys(task.orphanProps).length+(task.legacyOrphan&&!defs.includes('frequenza')?1:0);task.orphan=task.orphanCount>0;if(!task.isDraft){const doc=state.docs.find(d=>d.id===(task.noteDocId||(task.id===2?5:null)));if(doc){doc.space=space;doc.area=task.area}persist()}render();document.getElementById('task-space-select')?.focus();if(!task.isDraft)toast(`Task spostato in ${space}`)}
function createTaskFromDraft(){if(!taskDraft)return;const input=document.querySelector('.entity-title'),editor=document.getElementById('task-note-editor');taskDraft.title=input?.value.trim()||'';const error=document.getElementById('draft-task-error');if(!taskDraft.title){if(error){error.textContent='Dai un titolo al task prima di crearlo.';error.hidden=false}input?.setAttribute('aria-invalid','true');input?.setAttribute('aria-describedby','draft-task-error');input?.focus();return}if(editor)saveTaskNote(editor);const saved={...taskDraft};delete saved.isDraft;state.tasks.push(saved);taskDraft=null;taskDraftReturn=null;if(editor&&saved.note)saveTaskNote(editor);persist();taskId=saved.id;view='task';render();document.querySelector('.entity-title')?.focus();toast('Task creato')}
function cancelTaskDraft(){const previous=taskDraftReturn;taskDraft=null;taskDraftReturn=null;if(previous){view=previous.view;currentArea=previous.currentArea;currentSpace=previous.currentSpace;taskId=previous.taskId;docId=previous.docId;habitId=previous.habitId}else view='dashboard';render();document.querySelector('.page-heading .btn,.capture')?.focus()}
document.addEventListener('click',e=>{if(e.target.closest('[data-task-draft-create]'))createTaskFromDraft();if(e.target.closest('[data-task-draft-cancel]'))cancelTaskDraft()});
document.addEventListener('change',e=>{if(e.target.dataset.moveTask)moveTaskSpace(e.target.dataset.moveTask,e.target.value)});
document.addEventListener('input',e=>{if(taskDraft&&e.target.hasAttribute('data-task-title')&&Number(e.target.dataset.taskTitle)===taskDraft.id){taskDraft.title=e.target.value;const error=document.getElementById('draft-task-error');if(error)error.hidden=true;e.target.removeAttribute('aria-invalid');e.target.removeAttribute('aria-describedby')}});
document.addEventListener('keydown',e=>{if(taskDraft&&view==='task'&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();createTaskFromDraft()}});
function propertyRow(label,ico,control,meta=''){return `<div class="notion-property"><div class="property-label">${icon(ico)}<span class="od-field"><span>${esc(label)}</span>${meta?`<small>${esc(meta)}</small>`:''}</span></div><div class="property-value">${control}</div></div>`}
function taskPage(){const t=findTask(t=>t.id===taskId);return `<article class="entity" data-screen="entity-task">${taskDraftActions(t)}<div class="page-icon">${icon('check')}</div><div class="eyebrow">${esc(t.area||'Inbox')} / ${esc(t.space)}</div><input class="entity-title ${t.done?'done':''}" aria-label="Titolo task" placeholder="Nuovo task" value="${esc(t.title)}" data-task-title="${t.id}">${t.isDraft?'<p id="draft-task-error" class="error" hidden></p>':''}${t.date&&t.date<today&&!t.done?'<span class="pill">In ritardo</span>':''}<section class="notion-properties" aria-label="Campi core e proprietà del task"><div class="property-group" aria-label="Campi core">${propertyRow('Stato','habit',`<select id="task-status" class="property-select status-select" data-task-status="${t.id}" aria-label="Stato"><option value="open" ${!t.done?'selected':''}>Aperto</option><option value="completed" ${t.done?'selected':''}>Completato</option></select>`)}${propertyRow('Scadenza','calendar',`<input class="property-input date-value" type="date" value="${esc(t.date)}" data-task-date="${t.id}" aria-label="Scadenza">`)}${propertyRow('Space','folder',taskSpaceControl(t))}</div>${t.orphan?`<div class="notice">${t.orphanCount||1} ${(t.orphanCount||1)===1?'valore non visibile':'valori non visibili'} in questo Space</div>`:''}${Object.keys(t.props).length?`<div class="property-group inherited-properties" aria-label="Proprietà dello Space">${Object.entries(t.props).map(([k,v])=>{const origin=k==='costo'?t.space:k==='stima'?'Nando':t.area;const control=['frequenza','occasione'].includes(k)?`<select class="property-select ${v?'tag-select':''}" data-prop="${k}" data-task="${t.id}" aria-label="${esc(k)}"><option value="">Vuoto</option>${(k==='frequenza'?['giornaliera','settimanale','mensile']:['compleanno','anniversario','altro']).map(o=>`<option ${v===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input class="property-input" data-prop="${k}" data-task="${t.id}" aria-label="${esc(k)}" value="${esc(v)}" placeholder="Vuoto" ${['costo','stima'].includes(k)?'inputmode="decimal"':''}>`;return propertyRow(k,['costo','stima'].includes(k)?'number':['occasione','frequenza'].includes(k)?'tag':'text',control,'da '+origin)}).join('')}</div>`:''}${taskLocalProperties(t)}</section>${t.id===2?`<section class="capability"><div class="od-row">${icon('habit')}<h3>Habit</h3><span class="pill" style="margin-left:auto">Sola lettura</span></div><p>Atti d'amore — ${state.habits[0].n} su 3 questo mese</p><button class="link-btn" data-nav="habits">Apri in Habits →</button></section>`:''}<hr class="divider">${taskNotesEditor(t)}</article>`}
function knowledge(){const spaces=[...new Set([...areas.flatMap(a=>[...a.resources,...a.projects]),...state.docs.map(d=>d.space)])],scope=currentSpace||'Protocollo digiuno';const rows=state.docs.filter(d=>d.space===scope&&(`${d.title} ${d.excerpt}`).toLowerCase().includes(localQuery.toLowerCase()));return `<div data-screen="knowledge-list"><div class="eyebrow">${icon('book')} Knowledge</div>${heading(scope,`${state.docs.filter(d=>d.space===scope).length} documenti · La tua conoscenza, connessa.`,`<button class="btn primary" data-action="new-doc">${icon('plus')} Nuovo documento</button>`)}<label class="small muted">Space <select id="knowledge-space" aria-label="Space Knowledge">${spaces.map(s=>`<option ${s===scope?'selected':''}>${esc(s)}</option>`).join('')}</select></label><div class="knowledge-tools"><label><span class="sr-only">Cerca in questo Space</span><input id="local-query" placeholder="Cerca in questo Space…" value="${esc(localQuery)}"></label><span class="small muted">Modificati di recente ↓</span></div><div id="knowledge-table">${knowledgeTable(rows,scope)}</div></div>`}
function knowledgeTable(rows,scope){return rows.length?`<table class="data-table"><thead><tr><th>Titolo</th>${scope==='Protocollo digiuno'?'<th>Stato lettura</th><th>Fonte</th>':''}<th>Modificato</th></tr></thead><tbody>${rows.map(d=>`<tr><td><button data-nav="document" data-arg="${d.id}">${icon('file')} <strong>${esc(d.title)}</strong><small>${esc(d.excerpt)}</small></button></td>${scope==='Protocollo digiuno'?`<td><span class="pill">${d.read||'—'}</span></td><td>${d.id===1?'Link ↗':'—'}</td>`:''}<td class="muted">${esc(d.modified)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h3>Nessun documento trovato</h3><p>Prova un altro titolo o crea un documento.</p><button class="btn" data-action="new-doc">Nuovo documento</button></div>'}
function documentPage(){const d=state.docs.find(d=>d.id===docId);return `<article data-screen="document"><div class="eyebrow">${icon('file')} ${esc(d.area)} / ${esc(d.space)}</div>${heading(d.title,'',`<button class="btn" data-action="edit-doc">Modifica</button>`)}<div class="doc-properties">${d.space==='Protocollo digiuno'?`<span class="muted">Stato lettura <span class="pill">${d.read||'—'}</span></span><span class="muted">Fonte ${d.sourceUrl?`<a class="link-btn" href="${esc(d.sourceUrl)}" target="_blank" rel="noreferrer">Link ↗</a>`:'—'}</span>`:''}<span class="muted">Modificato ${esc(d.modified.toLowerCase())}</span><button class="link-btn" data-action="doc-details">Dettagli</button></div><div class="document-grid"><div class="prose">${d.body?esc(d.body).split('\n\n').map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join(''):d.id===1?`<p>Uno spazio per raccogliere gli appunti sul digiuno intermittente e tenere insieme le risorse del <button class="wiki" data-nav="space" data-arg="Protocollo digiuno">Protocollo digiuno</button>.</p><h2>Una struttura semplice</h2><p>Il protocollo distingue una finestra dedicata ai pasti e una di digiuno. Queste sono note personali di esempio, non indicazioni mediche.</p><ul><li>Annotare la routine e le osservazioni personali.</li><li>Collegare le fonti prima di modificare il protocollo.</li><li>Confrontare gli appunti con quelli sul <span class="broken" title="Documento non trovato" tabindex="0">Sonno profondo</span>.</li></ul><blockquote>La costanza si costruisce con una routine sostenibile.</blockquote><h3>Schema degli appunti</h3><table><thead><tr><th>Sezione</th><th>Contenuto</th></tr></thead><tbody><tr><td>Routine</td><td>Orari e contesto</td></tr><tr><td>Osservazioni</td><td>Note personali</td></tr></tbody></table><figure><svg viewBox="0 0 600 112" width="600" height="112" style="display:block;width:100%;height:auto" role="img" aria-label="Schema: routine, osservazione, revisione"><rect x="0" y="16" width="168" height="72" rx="8" fill="var(--soft)" stroke="var(--line)"/><rect x="216" y="16" width="168" height="72" rx="8" fill="var(--soft)" stroke="var(--line)"/><rect x="432" y="16" width="168" height="72" rx="8" fill="var(--soft)" stroke="var(--line)"/><path d="M176 52h32m184 0h32" stroke="var(--muted)"/><g fill="var(--fg)" font-family="system-ui" font-size="18" text-anchor="middle"><text x="84" y="59">Routine</text><text x="300" y="59">Osservazione</text><text x="516" y="59">Revisione</text></g></svg><figcaption>Schema di organizzazione delle note personali.</figcaption></figure><div class="notice">Le fonti e le osservazioni rimangono collegate al loro Space.</div><pre><code>space: Protocollo digiuno\nstato lettura: letto</code></pre><details><summary>Domande da approfondire</summary><p>Quali osservazioni vale la pena conservare nel tempo?</p></details><details open><summary>Collegamenti utili</summary><p><button class="wiki" data-nav="space" data-arg="Protocollo digiuno">Protocollo digiuno</button></p></details>`:'<div class="empty"><p>Inizia a scrivere il tuo documento.</p><button class="btn" data-action="edit-doc">Scrivi</button></div>'}</div><aside class="backlinks"><h3>Linkato da</h3>${state.docs.filter(x=>x.id!==d.id&&(x.body||'').toLowerCase().includes(d.title.toLowerCase())).map(b=>`<div class="backlink"><button class="link-btn" data-nav="document" data-arg="${b.id}">${esc(b.title)}</button><p class="small muted">${esc((b.body||'').split('\n\n')[0].slice(0,110))}</p></div>`).join('')||'<p class="muted">Nessun backlink registrato.</p>'}<hr class="divider"><h3>In questo Space</h3><button data-nav="space" data-arg="${esc(d.space)}">${icon('folder')} ${esc(d.space)}</button><p class="muted">I collegamenti mantengono il contesto, senza duplicare i documenti.</p></aside></div></article>`}
function habitWindowDays(){return Array.from({length:31},(_,i)=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+i-15);return {key:isoDay(d),day:d.getDate(),weekday:d.toLocaleDateString('it-IT',{weekday:'short'}),month:d.toLocaleDateString('it-IT',{month:'short'}),full:d.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}})}
function habitPeriodRange(h,key=today){const date=new Date(key+'T12:00:00'),first=new Date(date),last=new Date(date);if(h.period==='mese'){first.setDate(1);last.setMonth(last.getMonth()+1,0)}else if(h.period==='settimana'){first.setDate(first.getDate()-(first.getDay()+6)%7);last.setTime(first.getTime());last.setDate(first.getDate()+6)}return {start:isoDay(first),end:isoDay(last)}}
function habitDateLabel(key){return new Date(key+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'})}
function habitScore(h){if(h.paused)return {value:'—',label:'In pausa'};return h.n>=h.target?{value:'1 / 1',label:'Raggiunto'}:{value:'0 / 1',label:'In corso'}}
function habitWindowCell(h,d){const n=Number(h.checkins?.[d.key]||0),future=d.key>today,paused=h.paused&&d.key>='2026-10-15';const label=future?'Non valutato':paused?'In pausa':n?`${n} check-in`:'Storico non disponibile';return `<td class="${d.key===today?'habit-day-today':''} ${future?'habit-day-future':''}"><span class="habit-day-mark ${n&&!future?'has-evidence':''}" title="${esc(h.name)} · ${esc(d.full)}: ${label}" aria-label="${esc(d.full)}: ${label}">${future?'·':paused?icon('pause'):n?(n>1?n:icon('check')):'—'}</span></td>`}
function habitsPage(){const days=habitWindowDays(),rows=state.habits.filter(h=>!habitFilter||h.area===habitFilter);return `<section data-screen="habit-view"><div class="eyebrow">${icon('habit')} Abitudini</div>${heading('Habit','15 giorni passati, oggi e 15 giorni futuri.',`<button class="btn primary" data-action="new-habit">${icon('plus')} Nuovo habit</button>`)}<div class="habit-month-controls"><label for="habit-filter">Area <select id="habit-filter"><option value="">Tutte le aree</option>${areas.map(a=>`<option ${habitFilter===a.name?'selected':''}>${a.name}</option>`).join('')}</select></label><span class="muted small">${habitDateLabel(days[0].key)} — ${habitDateLabel(days[30].key)}</span><button class="btn" data-habit-center>Centra oggi</button></div><div class="habit-month-scroll" id="habit-month-scroll" tabindex="0" role="region" aria-label="Registrazioni su 31 giorni. Scorri per vedere tutte le date."><table class="habit-month-table"><caption class="sr-only">Check-in giornalieri; obiettivi valutati per il periodo proprio dell’abitudine.</caption><colgroup><col class="habit-month-name">${days.map(()=>'<col class="habit-month-day">').join('')}<col class="habit-month-action"></colgroup><thead><tr><th scope="col" class="habit-sticky-name">Abitudine</th>${days.map(d=>`<th scope="col" ${d.key===today?'class="habit-day-today" data-habit-today':''}><span class="od-cell"><span>${esc(d.weekday)}</span><strong>${d.day}</strong><span>${d.key===today?'Oggi':esc(d.month)}</span></span></th>`).join('')}<th scope="col" class="habit-sticky-action"><span class="sr-only">Check-in di oggi</span></th></tr></thead><tbody>${rows.map(h=>`<tr><th scope="row" class="habit-sticky-name"><button class="habit-detail-link" data-nav="habit-detail" data-arg="${h.id}"><span>${esc(h.name)}</span><small>${esc(h.area)} · ${h.target}/${h.period}</small></button><span class="habit-row-progress">${h.paused?'In pausa dal 15/10':`${h.n} di ${h.target} nel periodo`}</span></th>${days.map(d=>habitWindowCell(h,d)).join('')}<td class="habit-sticky-action"><button class="icon-btn habit-grid-check" data-check-habit="${h.id}" ${h.paused||h.n>=h.target?'disabled':''} aria-label="Check-in di oggi per ${esc(h.name)}" title="${h.paused?'In pausa':h.n>=h.target?'Obiettivo raggiunto':'Check-in di oggi'}">${icon(h.paused?'pause':h.n>=h.target?'check':'plus')}</button></td></tr>`).join('')||'<tr><td colspan="33"><div class="empty">Nessuna abitudine in questa Area.</div></td></tr>'}</tbody></table></div><div class="habit-grid-legend"><span>✓ Check-in registrato</span><span>— Storico non disponibile</span><span>Ⅱ In pausa</span><span>· Futuro, non valutato</span></div><p class="small muted">La griglia mostra le registrazioni giornaliere. Lo score dipende dall’obiettivo del giorno, della settimana o del mese.</p></section>`}
function habitDetailPage(){return renderHabitAnalytics()}
function centerHabitToday(){const scroller=document.getElementById('habit-month-scroll'),cell=scroller?.querySelector('[data-habit-today]');if(!scroller||!cell)return;const labelWidth=scroller.querySelector('.habit-sticky-name')?.offsetWidth||0,actionWidth=scroller.querySelector('.habit-sticky-action')?.offsetWidth||0;scroller.scrollLeft=Math.max(0,cell.offsetLeft-labelWidth-(scroller.clientWidth-labelWidth-actionWidth-cell.offsetWidth)/2)}
document.addEventListener('click',e=>{if(e.target.closest('[data-habit-center]'))centerHabitToday()});
let calendarMonth=new Date('2026-10-28T12:00:00'),calendarDay='2026-10-28';
function isoDay(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function moveCalendar(delta){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+delta,1,12);calendarDay=isoDay(calendarMonth);render();document.querySelector(`[data-action="calendar-${delta<0?'prev':'next'}"]`)?.focus()}
function calendarPage(){
 const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),first=new Date(year,month,1,12),offset=(first.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),cells=Math.ceil((offset+days)/7)*7;
 const title=first.toLocaleDateString('it-IT',{month:'long',year:'numeric'}),monthTasks=state.tasks.filter(t=>t.date&&t.date.slice(0,7)===isoDay(first).slice(0,7)),selected=state.tasks.filter(t=>t.date===calendarDay);
 return `<section data-screen="calendar">${heading('Calendario','I tuoi impegni, un mese alla volta.')}<div class="calendar-toolbar"><div class="od-row"><button class="btn" data-action="calendar-today">Oggi</button><button class="icon-btn" data-action="calendar-prev" aria-label="Mese precedente">‹</button><button class="icon-btn" data-action="calendar-next" aria-label="Mese successivo">›</button><h2 aria-live="polite">${esc(title)}</h2></div><span class="pill">Mese</span></div><div class="calendar-legend"><span class="od-row"><i class="calendar-dot"></i>Aperti</span><span class="od-row"><span aria-hidden="true">✓</span>Completati</span><span class="muted">${monthTasks.length} task nel mese</span></div><div class="month-grid" aria-label="${esc(title)}"><div class="week-head" aria-hidden="true">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(d=>`<div>${d}</div>`).join('')}</div><div class="month-days">${Array.from({length:cells},(_,i)=>{const date=new Date(year,month,1-offset+i,12),key=isoDay(date),outside=date.getMonth()!==month,items=state.tasks.filter(t=>t.date===key),open=items.filter(t=>!t.done).length;return `<div class="month-cell ${outside?'outside':''} ${key===today?'is-today':''} ${key===calendarDay?'is-selected':''}"><button class="calendar-day" data-calendar-day="${key}" aria-pressed="${key===calendarDay}" ${key===today?'aria-current="date"':''} aria-label="${esc(date.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}, ${items.length} task"><span>${date.getDate()}</span><small class="calendar-mobile-count">${items.length?`${items.length} task`:''}</small></button><div class="calendar-events">${items.slice(0,3).map(t=>`<button class="calendar-event ${t.done?'completed':''} ${key<today&&!t.done?'overdue':''}" data-nav="task" data-arg="${t.id}"><span aria-hidden="true">${t.done?'✓':'○'}</span><span class="od-clamp-2">${esc(t.title)}</span><span class="sr-only">${t.done?'Completato':key<today?'In ritardo':'Aperto'}</span></button>`).join('')}${items.length>3?`<button class="calendar-more" data-calendar-day="${key}">+${items.length-3} altri</button>`:''}</div>${items.length?`<span class="calendar-dots" aria-hidden="true">${open?'●':''}${items.some(t=>t.done)?' ✓':''}</span>`:''}</div>`}).join('')}</div></div><section class="calendar-agenda" aria-labelledby="agenda-heading"><div class="section-head"><h2 id="agenda-heading">${esc(new Date(calendarDay+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'}))}</h2><span class="number">${selected.length}</span>${calendarDay===today?'<span class="pill blue">Oggi</span>':''}</div>${selected.length?tasks(selected):'<p class="muted">Nessun task in scadenza in questo giorno.</p>'}</section><p class="small muted calendar-footnote">I task sono collocati nella data di scadenza. Seleziona un giorno per vederli tutti, oppure apri un task dalla griglia.</p></section>`
}
function page(){switch(view){case'dashboard':return dashboard();case'calendar':return calendarPage();case'area':case'space':return areaPage();case'task':return taskPage();case'knowledge':return knowledge();case'document':return documentPage();case'habits':return habitsPage();case'habit-detail':return habitDetailPage();case'areas':return heading('Le tue aree','Quattro prospettive sul tuo spazio personale.')+areas.map(a=>`<button class="space-row" data-nav="area" data-arg="${a.name}">${icon(a.icon)}<span class="od-field"><strong>${a.name}</strong><small>${a.projects.length} progetti · ${openCount(a.name)} task aperti</small></span>${icon('arrow')}</button>`).join('');case'inbox':return heading('Inbox','Cattura adesso, organizza dopo.',`<button class="btn primary" data-action="capture">${icon('plus')} Cattura rapida</button>`)+tasks(state.tasks.filter(t=>t.space==='Inbox'));default:return dashboard()}}
function modal(title,fields,onSave){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-fields').innerHTML=fields;document.getElementById('form-error').hidden=true;dialogAction=onSave;document.getElementById('edit-dialog').showModal();document.querySelector('#dialog-fields input,#dialog-fields textarea,#dialog-fields select')?.focus()}
function inputField(label,id,value='',type='text'){return `<label for="${id}">${label}<input id="${id}" type="${type}" value="${esc(value)}"></label>`}
function capture(){openTaskDraft()}
function action(a){if(a==='calendar-prev'){moveCalendar(-1);return}if(a==='calendar-next'){moveCalendar(1);return}if(a==='calendar-today'){calendarMonth=new Date(today+'T12:00:00');calendarDay=today;render();return}if(a==='collapse'){collapsed=!collapsed;render()}if(a==='theme'){state.theme=state.theme==='light'?'dark':'light';persist();render()}if(a==='capture')capture();if(a==='search')openSearch();if(a==='space-knowledge'){view='knowledge';render()}if(a==='new-doc'){modal('Nuovo documento',inputField('Titolo *','new-title')+`<p class="muted small">Space: ${esc(currentSpace||'Protocollo digiuno')}</p>`,()=>{const title=document.getElementById('new-title').value.trim();if(!title)return 'Inserisci il titolo del documento.';const id=Date.now(),space=currentSpace||'Protocollo digiuno';state.docs.push({id,title,space,area:areas.find(a=>[...a.resources,...a.projects].includes(space))?.name||'Salute',body:'',excerpt:'Documento vuoto',modified:'Oggi'});view='document';docId=id;return true})}if(a==='edit-doc'){const d=state.docs.find(d=>d.id===docId);modal('Modifica documento',inputField('Titolo *','edit-title',d.title)+`<label for="edit-body">Corpo del documento<textarea id="edit-body" rows="12">${esc(d.body|| (d.id===1?'Appunti sul Protocollo digiuno.\n\nVedi anche: Sonno profondo (documento non trovato).':''))}</textarea></label>`,()=>{const title=document.getElementById('edit-title').value.trim();if(!title)return 'Il titolo non può essere vuoto.';d.title=title;d.body=document.getElementById('edit-body').value;d.excerpt=d.body.slice(0,60);d.modified='Oggi';return true})}if(a==='edit-note'){const t=findTask(t=>t.id===taskId);modal('Nota del task',`<label for="edit-note">Contenuto<textarea id="edit-note" rows="6">${esc(t.note||'')}</textarea></label>`,()=>{t.note=document.getElementById('edit-note').value;const d=state.docs.find(d=>d.id===5&&t.id===2);if(d)d.body=t.note;return true})}if(a==='new-habit'){modal('Nuovo habit',inputField('Nome *','habit-name')+inputField('Obiettivo per periodo *','habit-goal','1','number')+'<label>Periodo<select id="habit-period"><option value="giorno">Giorno</option><option value="settimana">Settimana</option><option value="mese">Mese</option></select></label><label>Area<select id="habit-area">'+areas.map(a=>`<option>${a.name}</option>`).join('')+'</select></label>',()=>{const name=document.getElementById('habit-name').value.trim(),goal=Number(document.getElementById('habit-goal').value),period=document.getElementById('habit-period').value;if(!name||!Number.isInteger(goal)||goal<1)return 'Inserisci un nome e un obiettivo intero maggiore di zero.';state.habits.push({id:Date.now(),name,target:goal,n:0,period,area:document.getElementById('habit-area').value,streak:'0',prev:'Precedente',now:period==='giorno'?'28 ott':period==='mese'?'Ottobre':'26 ott–1 nov',next:'Successivo'});return true})}if(a==='source')toast('Fonte non specificata nel brief: nessun URL inventato.');if(a==='doc-details')toast('Documento personale · Proprietà ereditate e locali · Nessuna restrizione');if(a==='edit-space'){modal('Informazioni dello Space',`<p>${esc(currentSpace||currentArea)}</p><p class="muted">Le definizioni delle proprietà di Space sono prestabilite. Le proprietà locali appartengono alla singola entità.</p><label>Descrizione<textarea id="space-description" rows="4">${esc(state.descriptions?.[currentSpace||currentArea]||'')}</textarea></label>`,()=>{state.descriptions=state.descriptions||{};state.descriptions[currentSpace||currentArea]=document.getElementById('space-description').value;return true})}}
function checkHabit(id,source={type:'manual'}){const h=state.habits.find(h=>h.id===Number(id));if(!h||h.paused||h.n>=h.target)return;h.checkins=h.checkins||{};h.checkins[today]=(h.checkins[today]||0)+1;h.evidences=h.evidences||[];h.evidences.push({id:'evidence-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),date:today,occurredAt:new Date().toISOString(),quantity:1,source:source.type||'manual',...(source.taskId?{taskId:source.taskId}:{})});h.n++;if(h.summary)h.summary='25 su 31 giorni';persist();render();const button=document.querySelector(`[data-check-habit="${id}"]`);if(button&&!button.disabled)button.focus();else document.querySelector('.habit-back,.habit-summary .text-btn,.page-heading .btn,#habit-filter')?.focus();toast(h.n>=h.target?'Obiettivo del periodo raggiunto':'Check-in di oggi registrato')}
function saveModal(){const result=dialogAction?.();if(result!==true){const err=document.getElementById('form-error');err.textContent=result||'Controlla i campi.';err.hidden=false;return}persist();document.getElementById('edit-dialog').close();render();document.querySelector('.page-heading .btn,.capture')?.focus();toast('Modifiche salvate')}
let searchReturn=null;
function openSearch(){searchReturn=document.activeElement;document.getElementById('search-symbol').innerHTML=icon('search');document.getElementById('global-search').value='';searchIndex=0;searchResults('');document.getElementById('search-dialog').showModal();document.getElementById('global-search').focus()}
function searchResults(q){const results=document.getElementById('search-results');q=q.trim().toLowerCase();if(!q){searchMatches=[];results.innerHTML='<div class="search-intro"><h3>Cerca in tutti gli Space</h3><p class="small">Trova documenti e apri il risultato giusto.</p></div>';return}const corpus=state.docs.map(d=>{const body=d.body||d.excerpt||'',haystack=(d.title+' '+body).toLowerCase(),pos=haystack.indexOf(q);if(pos<0)return null;const bodyPos=body.toLowerCase().indexOf(q),start=Math.max(0,(bodyPos<0?0:bodyPos)-48),snippet=(bodyPos<0?body:body.slice(start,start+160)).replace(/\s+/g,' ').trim(),blocks=d.blocks||Math.max(1,(d.body||'').split(/\n\n+/).filter(Boolean).length);return {type:'document',id:d.id,title:d.title,crumb:d.area+' / '+d.space,snippet,blocks}}).filter(Boolean);searchMatches=corpus;searchIndex=Math.min(searchIndex,Math.max(0,searchMatches.length-1));const highlight=text=>{const s=String(text),i=s.toLowerCase().indexOf(q);return i<0?esc(s):esc(s.slice(0,i))+'<mark>'+esc(s.slice(i,i+q.length))+'</mark>'+esc(s.slice(i+q.length))};results.innerHTML=searchMatches.length?searchMatches.map((r,i)=>`<button class="search-result ${i===searchIndex?'selected':''}" data-search-open="${i}" tabindex="-1">${icon('file')} <strong>${highlight(r.title)}</strong><small>${esc(r.crumb)}</small><p>${highlight(r.snippet)}</p><small>${r.blocks} ${r.blocks===1?'blocco':'blocchi'}</small></button>`).join(''):`<div class="search-intro"><h3>Nessun risultato per “${esc(q)}”</h3><p class="small">Prova a cercare per titolo.</p></div>`}
function openResult(i){const r=searchMatches[i];if(!r)return;document.getElementById('search-dialog').close();nav(r.type,r.id)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.calendarDay){calendarDay=b.dataset.calendarDay;render();document.querySelector(`[data-calendar-day="${calendarDay}"]`)?.focus();return}if(b.dataset.close){document.getElementById(b.dataset.close).close();return}if(b.dataset.nav){if(b.dataset.nav==='knowledge')currentSpace='';nav(b.dataset.nav,b.dataset.arg)}if(b.dataset.action)action(b.dataset.action);if(b.dataset.checkHabit)checkHabit(b.dataset.checkHabit);if(b.dataset.searchOpen!==undefined)openResult(Number(b.dataset.searchOpen));if(b.id==='save-dialog')saveModal()});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.checkTask){const task=findTask(x=>x.id===Number(t.dataset.checkTask));task.done=t.checked;persist();render();document.querySelector(`[data-check-task="${task.id}"]`)?.focus();toast(task.done?'Task completato':'Task riaperto')}if(t.dataset.taskStatus){findTask(x=>x.id===Number(t.dataset.taskStatus)).done=t.value==='completed';persist();render();document.getElementById('task-status')?.focus()}if(t.dataset.taskDate){findTask(x=>x.id===Number(t.dataset.taskDate)).date=t.value;persist()}if(t.dataset.taskTitle){const task=findTask(x=>x.id===Number(t.dataset.taskTitle));if(t.value.trim())task.title=t.value.trim();else t.value=task.title;persist()}if(t.dataset.prop){findTask(x=>x.id===Number(t.dataset.task)).props[t.dataset.prop]=t.value;persist()}if(t.id==='knowledge-space'){currentSpace=t.value;localQuery='';render()}if(t.id==='habit-filter'){habitFilter=t.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){searchIndex=0;searchResults(e.target.value)}if(e.target.id==='local-query'){localQuery=e.target.value;const scope=currentSpace||'Protocollo digiuno';document.getElementById('knowledge-table').innerHTML=knowledgeTable(state.docs.filter(d=>d.space===scope&&(d.title+' '+d.excerpt).toLowerCase().includes(localQuery.toLowerCase())),scope)}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(document.getElementById('search-dialog').open)document.getElementById('search-dialog').close();else if(!document.getElementById('edit-dialog').open)openSearch()}if(e.target.id==='global-search'){if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(searchMatches.length){searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchMatches.length)%searchMatches.length;searchResults(e.target.value);document.querySelector('.search-result.selected')?.scrollIntoView({block:'nearest'})}}if(e.key==='Enter'){e.preventDefault();openResult(searchIndex)}}if(e.key==='Enter'&&document.getElementById('edit-dialog').open&&e.target.tagName==='INPUT'){e.preventDefault();saveModal()}if(e.key.toLowerCase()==='c'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!e.target.isContentEditable&&!e.metaKey&&!e.ctrlKey&&!document.querySelector('dialog[open]'))capture()});
document.getElementById('search-dialog').addEventListener('close',()=>{if(searchReturn?.isConnected)searchReturn.focus()});document.getElementById('edit-dialog').addEventListener('close',()=>document.querySelector('.page-heading .btn,.capture')?.focus());
render();
